function bkOf(r){ for(var i=0;i<BK.length;i++){ if(r.indexOf(BK[i][0] + " ") === 0) return {b:BK[i], rest:r.slice(BK[i][0].length + 1)}; } return null; }
function koRef(r){
  var o = bkOf(r); if(!o) return r;
  return o.b[1] + " " + o.rest + (o.rest.indexOf(":") < 0 ? "장" : "");
}
function koRefs(s){ return s ? s.split("; ").map(koRef).join("; ") : s; }
function bibleUrl(r){
  var o = bkOf(r); if(!o) return niv(r);
  return "https://www.bskorea.or.kr/bible/korbibReadpage.php?version=GAE&book=" + o.b[2] + "&chap=" + parseInt(o.rest, 10);
}
function koDate(d){
  if(!d) return d;
  if(d === "Date unknown") return "연대 미상";
  var pre = [["Passover week, "," 유월절 주간"],["Passover, "," 유월절"],["Easter morning, "," 부활절 아침"],["Easter evening, "," 부활절 저녁"],["Spring "," 봄"],
    ["40 days after Easter, ",", 부활 40일 후"],["Pentecost, "," 오순절"],["Good Friday, "," 성금요일"],["Winter "," 겨울"],["A week later, ",", 한 주 뒤"],["July "," 7월"],["Born "," 출생"]];
  var suf = "";
  for(var i=0;i<pre.length;i++){ if(d.indexOf(pre[i][0]) === 0){ suf = pre[i][1]; d = d.slice(pre[i][0].length); break; } }
  var c = /^c\. /.test(d); d = d.replace(/^c\. /, "");
  var m = d.match(/^AD (.+)$/); if(!m) return d + suf;
  var y = m[1], dec = /\ds/.test(y);
  return "주후 " + (dec ? y.replace(/(\d+)s/g, "$1") + "년대" : y + "년" + (c ? "경" : "")) + suf;
}
