function koCite(s){
  if(!s) return s;
  if(/^Nero /.test(s)) return "「네로 전」 " + s.slice(5);
  if(/^Claudius /.test(s)) return "「클라우디우스 전」 " + s.slice(9);
  for(var i=0;i<CITE.length;i++) s = s.split(CITE[i][0]).join(CITE[i][1]);
  return s;
}

