  for(var la=25; la<=45; la+=5) S("path", {d:dpath([P([6,la]), P([60,la])])}, grat);
  S("path", {class:"coastwash", d:MAP.land}, svg);
  S("path", {class:"land", d:MAP.land}, svg);
