  S("path", {class:"lake", d:MAP.lakes}, svg);
  HAND_LAKES.forEach(function(r){ S("path", {class:"lake", d:dpath(spline(r.concat([r[0]]).map(P), 6), true)}, svg); });
  var gr = S("g", null, svg);
  RIVERS.forEach(function(r){ S("path", {class:"river", d:dpath(spline(r.map(P), 6))}, gr); });
  var gReg = S("g", null, svg);
  REG.forEach(function(r){
    var p = P(r.ll), g = S("g", {class:"reg" + (r.c ? " " + r.c : "")}, gReg);
    var t = S("text", {x:0, y:4}, g); t.textContent = r.t;
    regEls.push({g:g, x:p[0], y:p[1], min:r.min, max:r.max, t:t, en:r.t});
  });
  gRoutes = S("g", null, svg);
  gPlaces = S("g", null, svg);
  gEv = S("g", {class:"evm", style:"display:none"}, svg);
  S("rect", {class:"evp", x:-9, y:-9, width:18, height:18, transform:"rotate(45)"}, gEv);
