  if(sc.scrollTo) sc.scrollTo({left:left, behavior:(smooth && !reduced) ? "smooth" : "auto"}); else sc.scrollLeft = left;
  $("prev").disabled = i === 0; $("next").disabled = i === state.ap.stops.length - 1;
