(function roadEvents(){
  var sc = $("roadScroll"), drag = null, suppress = false;
  sc.addEventListener("click", function(ev){
    if(suppress){ suppress = false; ev.preventDefault(); ev.stopPropagation(); return; }
    var b = ev.target.closest("[data-i]"); if(!b) return;
    selectStop(+b.getAttribute("data-i"));
  }, true);
  sc.addEventListener("pointerdown", function(ev){
    if(ev.pointerType !== "mouse" || ev.button !== 0) return;
    drag = {x:ev.clientX, left:sc.scrollLeft, moved:false, id:ev.pointerId};
  });
  window.addEventListener("pointermove", function(ev){
    if(!drag) return;
    var dx = ev.clientX - drag.x;
    if(!drag.moved && Math.abs(dx) > 5){ drag.moved = true; sc.classList.add("dragging"); }
    if(drag.moved) sc.scrollLeft = drag.left - dx;
  });
  window.addEventListener("pointerup", function(){
    if(drag && drag.moved){ suppress = true; setTimeout(function(){ suppress = false; }, 50); }
    drag = null; sc.classList.remove("dragging");
  });
  sc.addEventListener("keydown", function(ev){
    if(ev.key === "ArrowRight"){ ev.preventDefault(); selectStop(state.i + 1); }
    else if(ev.key === "ArrowLeft"){ ev.preventDefault(); selectStop(state.i - 1); }
    else if(ev.key === "Home"){ ev.preventDefault(); selectStop(0); }
    else if(ev.key === "End"){ ev.preventDefault(); selectStop(state.ap.stops.length - 1); }
  });
  $("prev").addEventListener("click", function(){ selectStop(state.i - 1); });
  $("next").addEventListener("click", function(){ selectStop(state.i + 1); });
  $("dPrev").addEventListener("click", function(){ selectStop(state.i - 1); });
  $("dNext").addEventListener("click", function(){ selectStop(state.i + 1); });
})();

